    test("homo_sapiens - nanopore [bam, bai, [], bed], [], [], true, false - regions") {

        when {
            process {
                """
                input[0] = channel.of([
                    [ id:'hg002' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/HG002_ont_sv_genotype/HG002_ont_sv_genotype.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/HG002_ont_sv_genotype/HG002_ont_sv_genotype.bam.bai', checkIfExists: true),
                    []
                ]).combine(channel.of("chr2\t71600000\t71700000").collectFile(name: 'regions.bed', newLine: true))
                input[1] = [[], []]
                input[2] = [[], []]
                input[3] = true
                input[4] = false
                """
            }
        }

        then {
            def vcf = path(process.out.vcf.get(0).get(1)).vcf
            assertAll(
                { assert process.success },
                { assert vcf.chromosomes == ['chr2'] as Set },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith("versions") },
                    file(process.out.tbi.get(0).get(1)).name,
                    vcf.summary,
                    vcf.variantsMD5,
                ).match() }
            )
        }

    }

}

process {
    withName: 'SNIFFLES' {
        ext.args = { genotype_vcf ? '' : '--minsupport 1 --no-qc --mapq 0' }
        ext.prefix = { genotype_vcf ? "${meta.id}_genotyped" : meta.id }
    }
}
